import{_ as a,o as e,c as s,a3 as i}from"./chunks/framework.B9qR_F1m.js";const u=JSON.parse('{"title":"Set up ripeat with your AI assistant","description":"","frontmatter":{},"headers":[],"relativePath":"ai-setup.md","filePath":"ai-setup.md"}'),n={name:"ai-setup.md"};function o(r,t,l,p,h,c){return e(),s("div",null,[...t[0]||(t[0]=[i('<h1 id="set-up-ripeat-with-your-ai-assistant" tabindex="-1">Set up ripeat with your AI assistant <a class="header-anchor" href="#set-up-ripeat-with-your-ai-assistant" aria-label="Permalink to &quot;Set up ripeat with your AI assistant&quot;">​</a></h1><p>Copy the prompt below and paste it into your AI assistant (Claude Code, Codex, or another that can run commands on your computer). The assistant installs the ripeat skill, then follows it to install ripeat and connect itself. It asks you before changing the machine.</p><h2 id="the-prompt" tabindex="-1">The prompt <a class="header-anchor" href="#the-prompt" aria-label="Permalink to &quot;The prompt&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Install the ripeat skill with `npx skills add https://ripeat.github.io/skills/ripeat/SKILL.md --skill ripeat`, then follow it to install ripeat and connect this assistant. Ask me before making changes.</span></span></code></pre></div><p>The skills installer needs Node.js. It asks where to install the skill; if Node.js or the installer is unavailable, use <a href="./agent-skill">the manual skill instructions</a>. The setup command supports Claude Code, Claude Desktop and Codex; the skill stops with an explanation for other clients rather than guessing their configuration.</p><h2 id="what-it-can-and-cannot-do" tabindex="-1">What it can and cannot do <a class="header-anchor" href="#what-it-can-and-cannot-do" aria-label="Permalink to &quot;What it can and cannot do&quot;">​</a></h2><ul><li><strong>It can</strong> install ripeat through Homebrew or Scoop, check the version, and register ripeat&#39;s MCP server with your assistant using <a href="./mcp#connecting"><code>ripeat mcp setup</code></a>, which shows the change, keeps a backup of any file it edits and asks first.</li><li><strong>It cannot</strong> install your tools (the prompt tells the assistant not to, and without <code>--allow-run</code> ripeat&#39;s server offers no install tool at all), accept a risk for you, or add <code>--yes</code>.</li><li>The prompt lives on this site over HTTPS, so what you paste is what is published here. An assistant is an instruction follower, not a lock: the real protections are ripeat&#39;s own confirmations and the <a href="./admin-policy">administrator policy</a>, not the wording of the prompt.</li></ul><p>An assistant that only has a shell can also use <a href="./agent-skill">the skill</a>.</p><p>After the restart, ask the assistant something like &quot;Set up git, node and ripgrep on this machine.&quot; It looks each one up, builds the plan and its risk rating, and gives you the <code>ripeat install</code> command to read and run yourself. To let it run the install after you confirm each run in its own app, see <a href="./mcp#letting-the-assistant-install-ripeat-mcp---allow-run-off-by-default">ripeat as an MCP server</a>.</p>',9)])])}const m=a(n,[["render",o]]);export{u as __pageData,m as default};
